/* Grace House lobby wall . Option E . heritage photographs
   Option D's page with the generative art replaced by the approved historic
   Sydney photo programme (ChatGPT review, approved by Michael 22 Oct 2026).

   CARRIED OVER FROM OPTION D VERBATIM: stage fit, clock, weather (own Open
   Meteo fetch with localStorage cache and stale dimming) and the 20s liveness
   heartbeat that kiosk-watchdog.sh counts. Do not change those here without
   changing them in option-d too.

   NEW HERE: the photo player and the grain layer.
     - Slide order, captions, credits and timing come from programme.js, which
       is generated by Desktop/CLAUDE/scripts/build-grace-heritage-screen.py.
     - Crossfade is 1.8s. The outgoing slide stays fully opaque UNDER the
       incoming one until the fade has finished, so there is never a dark dip.
     - Every image is decoded before its fade starts, so a slow decode on the
       N150 delays a change rather than showing a half drawn photo.
     - A photo that fails to load is skipped, never left as a blank.
     - If the programme stops advancing for three dwell periods the page
       reloads itself. The watchdogs cannot see a stuck slideshow because the
       grain keeps moving, so the page has to police itself.
     - The position survives a browser restart (localStorage), so the nightly
       refresh and any watchdog restart carry on where they left off instead
       of replaying the first photos.

   Test overrides in the URL: ?dwell=7  ?start=P012  ?nograin  ?layout=a|b|c */

(function () {
  'use strict';

  var W = 2436, H = 783;

  // ---------- stage fit (X8E top left capture contract) ----------
  function fit() {
    var sx = window.innerWidth / W;
    var sy = window.innerHeight / H;
    var kiosk = sx >= 1 && sy >= 1;
    var s = kiosk ? 1 : Math.min(sx, sy);
    document.documentElement.style.setProperty('--fit', s);
    document.documentElement.classList.toggle('kiosk-mode', kiosk);
  }

  // ---------- clock ----------
  // Each block exists in both bars so the layout can place it without moving
  // DOM, so every write goes to all copies.
  function setAll(sel, text) {
    var els = document.querySelectorAll(sel);
    for (var i = 0; i < els.length; i++) els[i].textContent = text;
  }

  function tick() {
    var d = new Date();
    var hh = String(d.getHours()).padStart(2, '0');
    var mm = String(d.getMinutes()).padStart(2, '0');
    var day = d.toLocaleDateString('en-AU', { weekday: 'short' }).toUpperCase();
    var date = d.toLocaleDateString('en-AU', { day: '2-digit', month: 'short' }).toUpperCase();
    setAll('[data-clock]', hh + ':' + mm);
    setAll('[data-date]', day + ' . ' + date);
  }

  // ---------- weather ----------
  // Self contained ON PURPOSE, exactly as option-d. Same Open Meteo endpoint,
  // same cache key, so switching between option-d and option-e keeps the last
  // reading on screen instead of starting blank.
  var WX_KEY = 'gh.optiond.weather.v1';
  var WX_URL = 'https://api.open-meteo.com/v1/forecast'
    + '?latitude=-33.87&longitude=151.21'
    + '&current=temperature_2m,weather_code'
    + '&daily=temperature_2m_max,temperature_2m_min,weather_code'
    + '&timezone=Australia/Sydney&forecast_days=4';

  var WMO = {
    0: 'Clear', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast',
    45: 'Fog', 48: 'Fog', 51: 'Light drizzle', 53: 'Drizzle', 55: 'Drizzle',
    56: 'Freezing drizzle', 57: 'Freezing drizzle',
    61: 'Light rain', 63: 'Rain', 65: 'Heavy rain',
    66: 'Freezing rain', 67: 'Freezing rain',
    71: 'Light snow', 73: 'Snow', 75: 'Heavy snow', 77: 'Snow grains',
    80: 'Showers', 81: 'Showers', 82: 'Heavy showers',
    85: 'Snow showers', 86: 'Snow showers',
    95: 'Thunderstorm', 96: 'Thunderstorm', 99: 'Thunderstorm'
  };
  function condition(code) { return WMO[code] || 'Sydney'; }

  function cacheGet() {
    try {
      var raw = localStorage.getItem(WX_KEY);
      if (!raw) return null;
      var o = JSON.parse(raw);
      if (!o || !o.data || !o.ts) return null;
      return { data: o.data, ageMs: Date.now() - o.ts };
    } catch (e) { return null; }
  }
  function cacheSet(data) {
    try { localStorage.setItem(WX_KEY, JSON.stringify({ data: data, ts: Date.now() })); }
    catch (e) { /* private mode or full: the screen still works */ }
  }

  function fetchWeather() {
    return fetch(WX_URL, { cache: 'no-store' }).then(function (r) {
      if (!r.ok) throw new Error('open-meteo HTTP ' + r.status);
      return r.json();
    }).then(function (j) {
      var c = j.current || {}, d = j.daily || {};
      if (c.temperature_2m == null) throw new Error('no temp');
      var days = (d.time || []).slice(1, 4).map(function (iso, i) {
        return {
          day: new Date(iso + 'T00:00:00')
            .toLocaleDateString('en-AU', { weekday: 'short' }).toUpperCase(),
          max: Math.round(d.temperature_2m_max[i + 1]),
          min: Math.round(d.temperature_2m_min[i + 1]),
          code: d.weather_code[i + 1]
        };
      });
      return { temp: Math.round(c.temperature_2m), code: c.weather_code, days: days };
    });
  }
  function paintWeather(w, ageMs) {
    if (!w) return;

    if (w.temp != null) setAll('[data-wx-temp]', w.temp + '°');

    setAll('[data-wx-cond]', condition(w.code));

    if (Array.isArray(w.days)) {
      var days = w.days.slice(0, 3);
      var slots = document.querySelectorAll('[data-forecast]');
      for (var i = 0; i < slots.length; i++) {
        var f = slots[i];
        f.textContent = '';
        days.forEach(function (d) {
          var el = document.createElement('span');
          el.className = 'wx-day';
          var a = document.createElement('span'); a.className = 'd'; a.textContent = d.day;
          var b = document.createElement('span'); b.className = 'hi'; b.textContent = d.max + '°';
          var s = document.createElement('span'); s.className = 'lo'; s.textContent = d.min + '°';
          el.appendChild(a); el.appendChild(b); el.appendChild(s);
          f.appendChild(el);
        });
      }
    }

    // Older than an hour reads as stale rather than confidently wrong.
    var stale = ageMs != null && ageMs > 3600000;
    var wraps = document.querySelectorAll('.blk-wx');
    for (var j = 0; j < wraps.length; j++) wraps[j].classList.toggle('is-stale', stale);
  }

  // Paint the cached reading synchronously at load so the wall is never blank
  // while the first request is in flight.
  function seedWeather() {
    var c = cacheGet();
    if (c) paintWeather(c.data, c.ageMs);
  }

  function refreshWeather() {
    fetchWeather().then(function (w) {
      cacheSet(w);
      paintWeather(w, 0);
    }).catch(function (e) {
      // Network down. Whatever the cache last held stays on screen and ages
      // visibly via the stale class, rather than blanking.
      var c = cacheGet();
      if (c) paintWeather(c.data, c.ageMs);
      console.warn('[weather]', e && e.message);
    });
  }

  // ---------- liveness heartbeat ----------
  // kiosk-watchdog.sh decides the renderer is alive by counting requests for
  // now-playing.json in the gh-server journal. Same 20s beat as option-d;
  // remove it and the watchdog restarts chromium every few minutes forever.
  function heartbeat() {
    fetch('../assets/now-playing.json?t=' + Date.now(), { cache: 'no-store' })
      .catch(function () { /* a 404 or a refusal still proves we are alive */ });
  }

  // ---------- photo programme ----------
  var PROG = window.GRACE_PROGRAMME || { slides: [], dwell_s: 40, fade_s: 1.8 };
  var SLIDES = PROG.slides || [];
  var q = new URLSearchParams(location.search);
  var DWELL_MS = Math.max(5, parseFloat(q.get('dwell')) || PROG.dwell_s || 40) * 1000;
  var FADE_MS = Math.round((PROG.fade_s || 1.8) * 1000) + 50;
  var DECODE_TIMEOUT_MS = 20000;
  var POS_KEY = 'gh.optione.pos.v1';

  var layers = null;
  var cur = -1, busy = false, lastAdvance = Date.now(), timer = null;
  var state = window.__player = { id: null, index: -1, advances: 0, failures: [], reloads: 0 };

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  // Same DOM as the approved preview's makeSlide(), so the approved CSS lands
  // exactly as it did in the 105 mock-ups.
  function makeSlide(s) {
    var slide = el('div', 'slide');
    slide.setAttribute('data-fit', s.fit);
    slide.setAttribute('data-photo', s.id);
    var backdrop = el('img', 'blur-field');
    backdrop.src = s.src; backdrop.alt = '';
    var area = el('div', 'photo-area');
    var photo = el('img', 'photo');
    photo.src = s.src; photo.alt = s.alt;
    area.appendChild(photo);
    var caption = el('div', 'photo-caption');
    caption.appendChild(el('span', 'photo-year', s.year));
    caption.appendChild(el('span', 'photo-location', s.location));
    var credit = el('div', 'photo-credit');
    credit.appendChild(el('span', '', s.credit1));
    credit.appendChild(el('span', '', s.credit2));
    // CC BY 2.0 photos only: the licence address, which the licence requires
    // on every public display (section 4(a)).
    if (s.credit3) credit.appendChild(el('span', '', s.credit3));
    slide.appendChild(backdrop);
    slide.appendChild(el('div', 'field-tone'));
    slide.appendChild(area);
    slide.appendChild(caption);
    slide.appendChild(credit);
    return slide;
  }

  function withTimeout(p, ms) {
    return new Promise(function (resolve, reject) {
      var t = setTimeout(function () { reject(new Error('decode timeout')); }, ms);
      p.then(function (v) { clearTimeout(t); resolve(v); },
             function (e) { clearTimeout(t); reject(e); });
    });
  }

  function savePos(i) {
    try { localStorage.setItem(POS_KEY, SLIDES[i].id); } catch (e) { /* fine */ }
  }
  function startIndex() {
    var want = q.get('start');
    if (!want) { try { want = localStorage.getItem(POS_KEY); } catch (e) { want = null; } }
    var i = -1;
    for (var k = 0; k < SLIDES.length; k++) if (SLIDES[k].id === want) i = k;
    // Resume on the photo AFTER the one last shown, unless one was asked for.
    if (i < 0) return 0;
    return q.get('start') ? i : (i + 1) % SLIDES.length;
  }

  // Warm the next photo during the dwell so its fade starts on time.
  function preload(i) {
    var s = SLIDES[i % SLIDES.length];
    if (!s) return;
    var im = new Image();
    im.src = s.src;
    if (im.decode) im.decode().catch(function () { /* show() handles failure */ });
  }

  function show(i, instant) {
    if (!SLIDES.length) return Promise.resolve(false);
    if (busy) return Promise.resolve('busy');
    busy = true;
    var s = SLIDES[i];
    var incoming = makeSlide(s);
    var imgs = incoming.querySelectorAll('img');
    var waits = [];
    for (var k = 0; k < imgs.length; k++) waits.push(withTimeout(imgs[k].decode(), DECODE_TIMEOUT_MS));
    return Promise.all(waits).then(function () {
      var previous = layers.querySelector('.is-current');
      if (previous) previous.style.zIndex = '1';
      incoming.style.zIndex = '2';
      incoming.style.transition = instant || !previous ? 'none' : '';
      layers.appendChild(incoming);
      incoming.getBoundingClientRect();
      incoming.classList.add('is-current');
      cur = i;
      lastAdvance = Date.now();
      state.id = s.id; state.index = i; state.advances++;
      savePos(i);
      var finish = function () {
        var kids = Array.prototype.slice.call(layers.children);
        kids.forEach(function (n) { if (n !== incoming) n.remove(); });
        busy = false;
      };
      if (instant || !previous) finish(); else setTimeout(finish, FADE_MS);
      return true;
    }, function (err) {
      busy = false;
      state.failures.push(s.id + ': ' + (err && err.message));
      console.error('[photo] skipped ' + s.id, err && err.message);
      return false;
    });
  }

  // Try the next photo; on failure try the one after, never more than one lap.
  function advance(from, instant, tries) {
    tries = tries || 0;
    if (tries >= SLIDES.length) { schedule(); return; }
    var i = (from + SLIDES.length) % SLIDES.length;
    show(i, instant).then(function (ok) {
      if (ok === 'busy') { setTimeout(function () { advance(i, instant, tries); }, 500); }
      else if (ok) { preload(i + 1); schedule(); }
      else advance(i + 1, instant, tries + 1);
    });
  }

  function schedule() {
    clearTimeout(timer);
    timer = setTimeout(function () { advance(cur + 1, false, 0); }, DWELL_MS);
  }

  function watchSelf() {
    setInterval(function () {
      if (Date.now() - lastAdvance > DWELL_MS * 3 + 60000) {
        console.error('[photo] programme stalled, reloading the page');
        location.reload();
      }
    }, 30000);
  }

  // ---------- grain ----------
  // One to two brightness levels, redrawn every second. See styles.css.
  function startGrain() {
    var cv = document.getElementById('grain');
    var host = document.querySelector('.hero');
    if (!cv || !host) return;
    if (q.has('nograin')) { cv.hidden = true; return; }
    var w = Math.max(1, Math.round(host.clientWidth / 4));
    var h = Math.max(1, Math.round(host.clientHeight / 4));
    cv.width = w; cv.height = h;
    var ctx = cv.getContext('2d');
    if (!ctx) return;
    var img = ctx.createImageData(w, h);
    var px = img.data;
    for (var k = 0; k < px.length; k += 4) { px[k] = px[k + 1] = px[k + 2] = 255; }
    function draw() {
      for (var k = 3; k < px.length; k += 4) px[k] = Math.random() < 0.5 ? 0 : 2;
      ctx.putImageData(img, 0, 0);
    }
    draw();
    setInterval(draw, 1000);
  }

  // ---------- init ----------
  function init() {
    // ?layout=a|b|c overrides the attribute, as in option-d.
    var lq = (location.search.match(/[?&]layout=([abc])/i) || [])[1];
    var stage = document.querySelector('.stage');
    if (lq && stage) stage.setAttribute('data-layout', lq.toLowerCase());

    fit();
    window.addEventListener('resize', fit);

    tick();
    setInterval(tick, 1000);

    seedWeather();
    refreshWeather();
    setInterval(refreshWeather, 600000); // 10 min, same cadence as option-b

    heartbeat();
    setInterval(heartbeat, 20000); // 20s, the cadence kiosk-watchdog.sh expects

    layers = document.getElementById('layers');
    startGrain();
    advance(startIndex(), true, 0);
    watchSelf();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
